<?php if($errors->any()): ?><div class="form-alert" role="alert"><?php echo e($errors->first()); ?></div><?php endif; ?>
<div class="form-section-title"><span class="form-section-number">01</span><div><h2>Agreement details</h2><p>Record the identifying details shown in the agreement.</p></div></div>
<div class="form-grid">
    <label class="field-span-2">Agreement title <span class="required-mark">*</span><input name="title" required maxlength="180" value="<?php echo e(old('title', $contract?->title)); ?>" placeholder="e.g. Cloud services agreement"></label>
    <label>Document type <span class="required-mark">*</span><select name="document_type" required><?php $__currentLoopData = ['Service agreement', 'Supplier agreement', 'Employment agreement', 'Non-disclosure agreement', 'Commercial agreement', 'Lease agreement', 'Amendment', 'Other']; $__env->addLoop($__currentLoopData); foreach($__currentLoopData as $type): $__env->incrementLoopIndices(); $loop = $__env->getLastLoop(); ?><option value="<?php echo e($type); ?>" <?php if(old('document_type', $contract?->document_type ?? 'Service agreement') === $type): echo 'selected'; endif; ?>><?php echo e($type); ?></option><?php endforeach; $__env->popLoop(); $loop = $__env->getLastLoop(); ?></select></label>
