    <?php if($contract): ?><label>Record status<select name="status"><option value="active" <?php if(old('status', $contract->status) === 'active'): echo 'selected'; endif; ?>>Active</option><option value="under_review" <?php if(old('status', $contract->status) === 'under_review'): echo 'selected'; endif; ?>>Under review</option><option value="archived" <?php if(old('status', $contract->status) === 'archived'): echo 'selected'; endif; ?>>Archived</option></select></label><?php endif; ?>
    <label class="field-span-2">Team summary <span class="field-hint">Optional · confirm against the document</span><textarea name="summary" rows="4" maxlength="10000" placeholder="Add a short working summary for your team"><?php echo e(old('summary', $contract?->summary)); ?></textarea></label>
